export function createMachine(config) {
  const machine = {
    state: config.initial,
    log: [],
    send(event) {
      const type = typeof event === 'string' ? event : event.type;
      const here = config.states[machine.state];
      const listed = here.on && here.on[type];
      if (!listed) return false;
      const options = Array.isArray(listed) ? listed : [listed];
      for (const option of options) {
        if (option.guard && !option.guard(event)) continue;
        if (option.action) machine.log.push(option.action);
        machine.state = option.target;
        return true;
      }
      return false;
    },
  };
  return machine;
}
